s = s.replace('  const [activeTab, setActiveTab] = useState<Tab>("home");\n', '  const [activeTab, setActiveTab] = useState<Tab>("home");\n  const [profileTab, setProfileTab] = useState<"posts" | "reels" | "reposts" | "tagged">("posts");\n', 1)
